import axios from "axios";

const API_BASE_URL = process.env.REACT_APP_API_URL || "http://localhost:5000";

// Fetch all deliveries
export const fetchDeliveries = () => axios.get(`${API_BASE_URL}/api/delivery`);

// Assign a driver to a specific delivery
export const assignDriver = (deliveryId: string, driverId: string) =>
  axios.put(`${API_BASE_URL}/api/delivery/${deliveryId}/assign`, { driverId });

// Get details of a specific delivery by its ID
export const getDeliveryById = (id: string) =>
  axios.get(`${API_BASE_URL}/api/delivery/${id}`);

// Create a new delivery entry
export const createDelivery = (delivery: {
    customerId: string;
    driverId?: string; // ✅ make optional
    location: {
      lat: number;
      lng: number;
    };
    status: string;
  }) => axios.post(`${API_BASE_URL}/api/deliveries`, delivery);
  

// Update delivery status (e.g., mark as Delivered)
export const updateDeliveryStatus = (deliveryId: string, status: string) =>
  axios.put(`${API_BASE_URL}/api/deliveries/status`, { deliveryId, status });
